import{_ as e,o,c,a2 as t}from"./chunks/framework.CiKk3sJz.js";const p=JSON.parse('{"title":"漫画 · 第 6 话 变量与 calc：CSS 的\\"运行时\\"与\\"计算器\\"","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.06-variables-calc.md","filePath":"comics/css/EP.06-variables-calc.md","lastUpdated":1792579602000}'),r={name:"comics/css/EP.06-variables-calc.md"};function d(l,a,s,i,n,h){return o(),c("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-6-话-变量与-calc-css-的-运行时-与-计算器" tabindex="-1">漫画 · 第 6 话 变量与 calc：CSS 的&quot;运行时&quot;与&quot;计算器&quot; <a class="header-anchor" href="#漫画-·-第-6-话-变量与-calc-css-的-运行时-与-计算器" aria-label="Permalink to &quot;漫画 · 第 6 话 变量与 calc：CSS 的&quot;运行时&quot;与&quot;计算器&quot;&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/06-variables-calc">docs/css/06-variables-calc.md</a> ｜ 原画：<a href="./EP.06-variables-calc.svg">EP.06-variables-calc.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。被散落全项目的 37 处写死色值折磨，改个品牌色漏改一处就&quot;花&quot;。</li><li><strong>标签君</strong>：HTML5 结构师，演示 <code>:root</code> 与 <code>.card</code> 的作用域嵌套，以及一行 JS 全站换色的魔法。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>自定义属性与预处理变量的本质区别是&quot;它是活的&quot;：参与层叠、被 DOM 继承、可在运行时被 JS 修改。像素酱把魔法数字收敛进变量，学会用继承作用域换肤、用 <code>var()</code> 回退值兜底、用 calc 家族做混合单位运算，最后靠 <code>@property</code> 让变量也能参与动画。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p><code>#4361ee</code> 这类&quot;魔法数字&quot;写死在无数条声明里，改主题色 = 全局搜索替换，漏改一处界面就花了。解法是把值收敛到 <code>:root</code> 的变量里：<code>--brand: #4361ee</code>，所有地方引用 <code>var(--brand)</code>，改一处全站生效，顺便消灭魔法数字。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>变量沿 DOM 树向下继承，子元素取&quot;最近祖先&quot;的值——在 <code>.card</code> 上覆盖 <code>--accent</code>，其后代吃到品红，出了卡片自动还原全局的青色，<strong>主题切换的本质就是利用继承的作用域覆盖</strong>。JS 侧 <code>el.style.setProperty(&#39;--brand&#39;, …)</code> 一行即全站换色；<code>var(--gap, 8px)</code> 的回退值在变量未定义时兜底，避免&quot;invalid at computed-value time&quot;整条声明失效。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>主题三段式：亮色写 <code>:root</code> 默认 → 暗色写 <code>[data-theme=&quot;dark&quot;]</code> 覆盖同一组变量 → JS 改 <code>dataset.theme</code> 并用 localStorage 记住选择。<code>calc()</code> 让混合单位互相运算（<code>100% - 240px</code>），但<strong>运算符两侧必须有空格</strong>。未注册的变量对浏览器只是字符串、动画只能跳变；<code>@property</code> 声明 <code>syntax: &#39;&lt;angle&gt;&#39;</code> 等类型后，变量即可参与 transition/keyframes 逐帧插值。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>变量参与层叠与继承，换肤 = 换一组变量；高频变化的变量挂在尽可能小的子树根上。</li><li>calc 运算符两侧必须有空格：<code>calc(100% - 10px)</code> 对，<code>calc(100%-10px)</code> 直接解析失败。</li><li>未注册的变量是字符串不能插值；<code>@property</code> 注册类型后才能参与过渡与动画。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：在 <code>.card</code> 上覆盖了 <code>--accent: red</code>，卡片<strong>外部</strong>的 <code>.tag { background: var(--accent) }</code> 是什么颜色？为什么？</p><p><strong>答</strong>：全局 <code>:root</code> 里 <code>--accent</code> 的颜色。变量沿 DOM 继承、取最近祖先，<code>.card</code> 的覆盖只影响其后代，出了卡片自动还原——这正是&quot;作用域即换肤边界&quot;，也是暗色模式只需在根节点覆盖一组变量的原理。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>变量作用域、继承与 JS <code>setProperty</code> 联动：<a href="./../../examples/css/06-variables-calc/index-01-variable-basics.html">examples/css/06-variables-calc/</a></li><li><code>calc()/min()/max()/clamp()</code> 流体排版与安全间距：<a href="./../../examples/css/06-variables-calc/index-02-fluid-typography.html">index-02-fluid-typography.html</a></li><li>主题切换实战：<code>data-theme</code> + <code>localStorage</code> 记忆：<a href="./../../examples/css/06-variables-calc/index-03-theme-switcher.html">index-03-theme-switcher.html</a></li><li><code>@property</code> 注册类型 + 变量驱动的动画：<a href="./../../examples/css/06-variables-calc/index-04-property-registration.html">index-04-property-registration.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 7 话《阴影》——界面的海拔系统：box-shadow、text-shadow、drop-shadow 三兄弟分工。</p>',22)])])}const m=e(r,[["render",d]]);export{p as __pageData,m as default};
